-- =============================================================================
-- SCRIPT DDL: Tablas e Índices para AdoptMe en PostgreSQL (Neon)
-- Generado a partir de AdoptMeDbContext, Usuario.cs y Mascota.cs
-- =============================================================================

-- 1. Tabla de Mascotas
CREATE TABLE IF NOT EXISTS "Mascotas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Species" character varying(50) NOT NULL,
    "Breed" character varying(100) NOT NULL,
    "Age" character varying(30) NOT NULL,
    "Gender" character varying(30) NOT NULL,
    "Location" character varying(150) NOT NULL,
    "Status" character varying(30) NOT NULL,
    "Description" character varying(2000) NOT NULL,
    "ImageUrl" text,
    "CreadoPorCorreo" character varying(200) NOT NULL,
    "FechaCreacion" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Mascotas" PRIMARY KEY ("Id")
);

-- 2. Tabla de Usuarios
CREATE TABLE IF NOT EXISTS "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "Correo" text NOT NULL,
    "PasswordHash" text NOT NULL,
    "Telefono" text NOT NULL,
    "Rol" text NOT NULL,
    "FechaRegistro" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id")
);

-- 3. Índice único para el correo de Usuario
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Usuarios_Correo" ON "Usuarios" ("Correo");

